    #[test]
    fn session_tool_result_usage_groups_returned_content_by_tool() {
        fn message(
            id: &str,
            role: crate::session::models::MessageRole,
            content: &str,
            tool_calls: Option<Vec<ToolCallInfo>>,
            tool_call_id: Option<&str>,
        ) -> ChatMessage {
            ChatMessage {
                id: id.to_string(),
                role,
                content: content.to_string(),
                created_at: 0,
                prompt_prefix: None,
                prompt_suffix: None,
                response_id: None,
                content_order: None,
                thinking_order: None,
                tool_calls,
                tool_call_id: tool_call_id.map(str::to_string),
                images: None,
                asset_refs: None,
                thinking_content: None,
                thinking_duration: None,
                thinking_signature: None,
                knowledge_proposal: None,
                render_parts: None,
            }
        }

        let tool_call = |id: &str, name: &str| ToolCallInfo {
            id: id.to_string(),
            name: name.to_string(),
            arguments: "{}".to_string(),
            order: None,
            server_tool: None,
            server_tool_output: None,
            outcome: None,
            recorded_output: None,
            nested_tool_calls: None,
        };
        let messages = vec![
            message(
                "assistant-1",
                crate::session::models::MessageRole::Assistant,
                "",
                Some(vec![
                    tool_call("call-1", "read"),
                    tool_call("call-2", "read"),
                ]),
                None,
            ),
            message(
                "result-1",
                crate::session::models::MessageRole::Tool,
                "short result",
                None,
                Some("call-1"),
            ),
            message(
                "result-2",
                crate::session::models::MessageRole::Tool,
                "a much longer returned result that consumes more input tokens",
                None,
                Some("call-2"),
            ),
        ];

        let usage = estimate_session_tool_result_usage(&messages);
        assert_eq!(usage.len(), 1);
        assert_eq!(usage[0].name, "read");
        assert_eq!(usage[0].call_count, 2);
        assert!(usage[0].result_tokens > 0);
    }

    #[test]
    fn subagent_failure_recovers_assistant_text_as_an_interrupted_result() {
        fn message(role: crate::session::models::MessageRole, content: &str) -> ChatMessage {
            ChatMessage {
                id: uuid::Uuid::new_v4().to_string(),
                role,
                content: content.to_string(),
                created_at: 0,
                prompt_prefix: None,
                prompt_suffix: None,
                response_id: None,
                content_order: None,
                thinking_order: None,
                tool_calls: None,
                tool_call_id: None,
                images: None,
                asset_refs: None,
                thinking_content: None,
                thinking_duration: None,
                thinking_signature: None,
                knowledge_proposal: None,
                render_parts: None,
            }
        }

        let messages = vec![
            message(
                crate::session::models::MessageRole::User,
                "inspect the project",
            ),
            message(
                crate::session::models::MessageRole::Assistant,
                "First recovered finding.",
            ),
            message(
                crate::session::models::MessageRole::Tool,
                "internal tool output",
            ),
            message(
                crate::session::models::MessageRole::Assistant,
                &format!(
                    "{}\ninternal compact summary",
                    crate::compact::CONTEXT_HANDOFF_MARKER
                ),
            ),
            message(
                crate::session::models::MessageRole::Assistant,
                "Second recovered finding.",
            ),
        ];

        let (output, outcome) = subagent_failure_result(&messages, "network disconnected");

        assert_eq!(outcome, ToolRunOutcome::Interrupted);
        assert!(output.contains("First recovered finding."));
        assert!(output.contains("Second recovered finding."));
        assert!(output.contains("Failure: network disconnected"));
        assert!(!output.contains("inspect the project"));
        assert!(!output.contains("internal tool output"));
        assert!(!output.contains("internal compact summary"));

        let (output, outcome) = subagent_failure_result(&messages[..1], "request rejected");
        assert_eq!(outcome, ToolRunOutcome::Error);
        assert_eq!(output, "Subagent error: request rejected");
    }

    #[tokio::test]
    async fn abort_on_drop_task_cancels_detached_subagent_work() {
        struct DropSignal(Option<tokio::sync::oneshot::Sender<()>>);

        impl Drop for DropSignal {
            fn drop(&mut self) {
                if let Some(sender) = self.0.take() {
                    let _ = sender.send(());
                }
            }
        }

        let (started_tx, started_rx) = tokio::sync::oneshot::channel();
        let (dropped_tx, dropped_rx) = tokio::sync::oneshot::channel();
        let task = AbortOnDropTask::new(tokio::spawn(async move {
            let _drop_signal = DropSignal(Some(dropped_tx));
            let _ = started_tx.send(());
            std::future::pending::<()>().await;
        }));

        started_rx.await.expect("spawned task should start");
        drop(task);

        tokio::time::timeout(std::time::Duration::from_secs(1), dropped_rx)
            .await
            .expect("aborted task should be dropped promptly")
            .expect("drop signal should be delivered");
    }

    #[tokio::test]
    async fn async_start_returns_an_immediate_failure_and_marks_it_handled() {
        let (result_tx, result_rx) = tokio::sync::oneshot::channel();
        let (handled_tx, handled_rx) = tokio::sync::oneshot::channel();
        result_tx
            .send(ExecutedToolResult::from_tool_result(ToolResult {
                output: "failed to start".to_string(),
                is_error: true,
            }))
            .expect("startup result receiver");

        let result = receive_immediate_async_failure(
            result_rx,
            handled_tx,
            std::time::Duration::from_secs(1),
        )
        .await
        .expect("immediate startup failure");

        assert_eq!(result.output, "failed to start");
        assert!(result.is_error);
        assert!(handled_rx.await.expect("handled decision"));
    }

    #[tokio::test]
    async fn async_start_keeps_immediate_success_and_pending_work_as_tasks() {
        let (success_tx, success_rx) = tokio::sync::oneshot::channel();
        let (success_handled_tx, success_handled_rx) = tokio::sync::oneshot::channel();
        success_tx
            .send(ExecutedToolResult::from_tool_result(ToolResult {
                output: "done".to_string(),
                is_error: false,
            }))
            .expect("startup result receiver");

        assert!(receive_immediate_async_failure(
            success_rx,
            success_handled_tx,
            std::time::Duration::from_secs(1),
        )
        .await
        .is_none());
        assert!(!success_handled_rx.await.expect("handled decision"));

        let (_pending_tx, pending_rx) = tokio::sync::oneshot::channel();
        let (pending_handled_tx, pending_handled_rx) = tokio::sync::oneshot::channel();
        assert!(receive_immediate_async_failure(
            pending_rx,
            pending_handled_tx,
            std::time::Duration::ZERO,
        )
        .await
        .is_none());
        assert!(!pending_handled_rx.await.expect("handled decision"));
    }

