    #[test]
    fn model_follow_up_requires_executable_tools_or_explicit_continuation() {
        assert!(!model_response_needs_follow_up(&[], None));
        assert!(!model_response_needs_follow_up(&[], Some(true)));
        assert!(model_response_needs_follow_up(&[], Some(false)));

        let mut server_tool = test_tool_call("search-1", "web_search", json!({"query": "locus"}));
        server_tool.server_tool = Some(ServerToolKind::WebSearch);
        server_tool.server_tool_output = Some("result".to_string());

        assert!(!model_response_needs_follow_up(
            std::slice::from_ref(&server_tool),
            None,
        ));
        assert!(!model_response_needs_follow_up(
            std::slice::from_ref(&server_tool),
            Some(true),
        ));
        assert!(model_response_needs_follow_up(
            std::slice::from_ref(&server_tool),
            Some(false),
        ));

        let local_tool = test_tool_call("read-1", "read", json!({"filePath": "README.md"}));
        assert!(model_response_needs_follow_up(
            std::slice::from_ref(&local_tool),
            Some(true),
        ));
        assert!(model_response_needs_follow_up(
            &[server_tool, local_tool],
            Some(true),
        ));
    }

    #[test]
    fn plans_parallel_edit_batches_by_normalized_file_path() {
        let root = tempdir().expect("temp dir");
        let first_path = root.path().join("first.txt");
        let first_alias = root.path().join("nested").join("..").join("first.txt");
        let second_path = root.path().join("second.txt");
        let prepared = vec![
            (
                test_tool_call("edit-1", "edit", json!({})),
                json!({
                    "filePath": first_path,
                    "oldString": "alpha",
                    "newString": "ALPHA"
                }),
            ),
            (
                test_tool_call("edit-2", "edit", json!({})),
                json!({
                    "filePath": second_path,
                    "oldString": "beta",
                    "newString": "BETA"
                }),
            ),
            (
                test_tool_call("edit-3", "edit", json!({})),
                json!({
                    "filePath": first_alias,
                    "oldString": "gamma",
                    "newString": "GAMMA",
                    "replaceAll": true
                }),
            ),
        ];

        let batches = AgentInstance::plan_parallel_edit_batches(&prepared, &HashSet::new())
            .expect("parallel edit plan");

        assert_eq!(batches.len(), 2);
        assert_eq!(batches[0].member_indices, vec![0, 2]);
        assert_eq!(batches[1].member_indices, vec![1]);
        assert_eq!(
            batches[0].arguments["edits"]
                .as_array()
                .expect("batched edits")
                .len(),
            2
        );
        assert_eq!(batches[0].arguments["edits"][1]["oldString"], "gamma");
        assert_eq!(batches[0].arguments["edits"][1]["replaceAll"], true);
    }

    #[test]
    fn parallel_edit_plan_requires_multiple_direct_edit_calls() {
        let path = tempdir().expect("temp dir").path().join("file.txt");
        let single = vec![(
            test_tool_call("edit-1", "edit", json!({})),
            json!({
                "filePath": path,
                "oldString": "alpha",
                "newString": "ALPHA"
            }),
        )];
        assert!(AgentInstance::plan_parallel_edit_batches(&single, &HashSet::new()).is_none());

        let mut mixed = single;
        mixed.push((
            test_tool_call("write-1", "write", json!({})),
            json!({"filePath": "new.txt", "content": "new"}),
        ));
        assert!(AgentInstance::plan_parallel_edit_batches(&mixed, &HashSet::new()).is_none());
    }

    #[test]
    fn workspace_coordination_bypasses_reads_and_classifies_writes() {
        let root = tempdir().expect("temp dir");
        let external = tempdir().expect("external temp dir");
        let agent = test_agent_instance(root.path().to_string_lossy().to_string());

        for tool in ["read", "grep", "list", "todowrite"] {
            assert!(
                agent
                    .workspace_execution_request_for_tool(tool, &json!({}))
                    .is_none(),
                "{tool} must bypass workspace mutation coordination"
            );
        }

        let write = agent
            .workspace_execution_request_for_tool(
                "write",
                &json!({"filePath": root.path().join("same.txt")}),
            )
            .expect("write request");
        assert!(matches!(write, WorkspaceExecutionLockRequest::PathWrite(_)));
        assert!(matches!(
            agent.workspace_execution_request_for_tool("unity_execute", &json!({})),
            Some(WorkspaceExecutionLockRequest::Exclusive)
        ));
        let readonly_unity_execute = json!({"readonly": true});
        assert!(agent
            .workspace_execution_request_for_tool("unity_execute", &readonly_unity_execute)
            .is_none());
        assert!(!agent.tool_call_needs_undo_tracking("unity_execute", &readonly_unity_execute));
        assert!(AgentInstance::is_readonly_tool_call(
            "unity_execute",
            &readonly_unity_execute
        ));
        assert!(
            !agent.tool_call_has_unity_execution_barrier("unity_execute", &readonly_unity_execute)
        );
        let writable_unity_execute = json!({"readonly": false});
        assert!(matches!(
            agent.workspace_execution_request_for_tool("unity_execute", &writable_unity_execute),
            Some(WorkspaceExecutionLockRequest::Exclusive)
        ));
        assert!(agent.tool_call_needs_undo_tracking("unity_execute", &writable_unity_execute));
        assert!(
            agent.tool_call_has_unity_execution_barrier("unity_execute", &writable_unity_execute)
        );
        assert!(matches!(
            agent.workspace_execution_request_for_tool("bash", &json!({})),
            Some(WorkspaceExecutionLockRequest::Exclusive)
        ));
        let readonly_bash = json!({
            "workdir": root.path(),
            "readonly": true,
        });
        assert!(agent
            .workspace_execution_request_for_tool("bash", &readonly_bash)
            .is_none());
        assert!(!agent.tool_call_needs_undo_tracking("bash", &readonly_bash));
        assert!(AgentInstance::is_readonly_tool_call("bash", &readonly_bash));

        let external_write_bash = json!({
            "workdir": external.path(),
            "readonly": false,
        });
        assert!(agent
            .workspace_execution_request_for_tool("bash", &external_write_bash)
            .is_none());
        assert!(!agent.tool_call_needs_undo_tracking("bash", &external_write_bash));
        assert!(!AgentInstance::is_readonly_tool_call(
            "bash",
            &external_write_bash
        ));

        let primary_write_bash = json!({
            "workdir": root.path(),
            "readonly": false,
        });
        assert!(matches!(
            agent.workspace_execution_request_for_tool("bash", &primary_write_bash),
            Some(WorkspaceExecutionLockRequest::Exclusive)
        ));
        assert!(agent.tool_call_needs_undo_tracking("bash", &primary_write_bash));
        assert!(matches!(
            agent.background_workspace_execution_request_for_tool(
                "bash",
                &json!({}),
                "assistant-batch"
            ),
            Some(WorkspaceExecutionLockRequest::ParallelOpaque(group))
                if group == "assistant-batch"
        ));
        assert!(agent
            .background_workspace_execution_request_for_tool(
                "bash",
                &readonly_bash,
                "assistant-batch"
            )
            .is_none());
        assert!(agent
            .background_workspace_execution_request_for_tool(
                "bash",
                &external_write_bash,
                "assistant-batch"
            )
            .is_none());
        assert!(matches!(
            agent.background_workspace_execution_request_for_tool(
                "unity_execute",
                &json!({}),
                "assistant-batch"
            ),
            Some(WorkspaceExecutionLockRequest::Exclusive)
        ));
        assert!(agent
            .background_workspace_execution_request_for_tool(
                "subagent",
                &json!({}),
                "assistant-batch"
            )
            .is_none());
    }

    #[test]
    fn script_capable_subagents_use_conservative_workspace_scheduling() {
        let agent_dir = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../agent");
        let mut agent = test_agent_instance(String::new());
        agent.registry = Arc::new(AgentDefRegistry::load(Some(agent_dir.as_path()), None));
        agent.tool_registry = Arc::new(ToolRegistry::with_builtins());

        let explorer = agent.registry.get("explorer").expect("Explorer should load");
        let mut static_explorer = explorer.clone();
        static_explorer.tools.retain(|name| name != "unity_execute");
        assert!(agent.agent_definition_is_workspace_readonly(&static_explorer));

        // Prompt instructions cannot prove every future C# call is read-only.
        // Individual calls still use their explicit readonly argument.
        assert!(!agent.subagent_call_is_workspace_readonly(
            "subagent",
            &json!({"subagent_type": "explorer"})
        ));
        assert!(!agent
            .subagent_call_is_workspace_readonly("subagent", &json!({"subagent_type": "git"})));
        assert!(!agent.subagent_call_is_workspace_readonly(
            "tool_call",
            &json!({
                "toolName": "subagent",
                "arguments": {"subagent_type": "explorer"}
            })
        ));

        agent.mark_plan_readonly_subagent();
        assert!(agent.subagent_call_is_workspace_readonly(
            "subagent",
            &json!({"subagent_type": "explorer"})
        ));
        assert!(
            agent.subagent_call_is_workspace_readonly("subagent", &json!({"subagent_type": "git"}))
        );
    }

    #[test]
    fn compact_start_event_serializes_trigger_for_frontend() {
        let event = StreamEvent::CompactStart {
            session_id: "session-1".to_string(),
            context_tokens: 142_800,
            context_limit: 258_400,
            trigger: Some(CompactTrigger::Reactive),
        };
        let value = serde_json::to_value(&event).expect("serialize compact start");

        assert_eq!(value["type"], "compactStart");
        assert_eq!(value["contextTokens"], 142_800);
        assert_eq!(value["contextLimit"], 258_400);
        assert_eq!(value["trigger"], "reactive");

        // Events persisted before the field existed still deserialize.
        let legacy: StreamEvent = serde_json::from_value(json!({
            "type": "compactStart",
            "sessionId": "session-1",
            "contextTokens": 1,
            "contextLimit": 2
        }))
        .expect("deserialize legacy compact start");
        match legacy {
            StreamEvent::CompactStart { trigger, .. } => assert_eq!(trigger, None),
            other => panic!("unexpected event variant: {other:?}"),
        }

        let untriggered = StreamEvent::CompactStart {
            session_id: "session-1".to_string(),
            context_tokens: 1,
            context_limit: 2,
            trigger: None,
        };
        let value = serde_json::to_value(&untriggered).expect("serialize compact start");
        assert!(value.get("trigger").is_none());
    }

